package evparser

import "fmt"

// evLexAdapter implements the evLexer interface generated by goyacc.
// It wraps the hand-written lexer (tokenizer) and feeds tokens to the LALR parser.
type evLexAdapter struct {
	lex    *lexerState
	result Events
	err    string
}

// Lex returns the next token for goyacc.
func (l *evLexAdapter) Lex(lval *evSymType) int {
	t := l.lex.next()
	switch t.typ {
	case tokEOF:
		return 0
	case tokSYMBOL:
		lval.str = t.val
		return EV_SYMBOL
	case tokCOMMA:
		return EV_COMMA
	case tokLPAREN:
		return EV_LPAREN
	case tokRPAREN:
		return EV_RPAREN
	case tokLBR:
		return EV_LBR
	case tokRBR:
		return EV_RBR
	case tokLCB:
		return EV_LCB
	case tokRCB:
		return EV_RCB
	case tokSEMI:
		return EV_SEMI
	case tokCOLON:
		return EV_COLON
	case tokGT:
		return EV_GT
	case tokLT:
		return EV_LT
	default:
		return 0
	}
}

// Error is called by the generated parser on syntax errors.
func (l *evLexAdapter) Error(s string) {
	l.err = s
}

// Parse parses an event trace string into Events using the LALR(1) parser.
func Parse(s string) (Events, error) {
	lex := newLexer(s)
	adapter := &evLexAdapter{lex: lex}
	ret := evParse(adapter)
	if ret != 0 || adapter.err != "" {
		if adapter.err != "" {
			return nil, fmt.Errorf("parse error: %s", adapter.err)
		}
		return nil, fmt.Errorf("parse error (code %d)", ret)
	}
	return adapter.result, nil
}
